  ('Artificial Home', null, '#e0457b', '#c9956b', 'light', 'hello@artificialhome.demo', '+880 1712-345678', 'Artificial Home — Artificial Jewellery & Accessories in Bangladesh', 'Shop trendy artificial jewellery, bangles, earrings, necklaces, hair clips and beauty care. Cash on Delivery and bKash, Nagad, Rocket all over Bangladesh.', 'Trendy artificial jewellery, hair accessories and beauty care — made for every girl, delivered all over Bangladesh.', 'Shop Now', '[]'::jsonb, 'Free delivery on orders over ৳2,000 · Cash on Delivery all over Bangladesh', '8801712345678', 60, 120, 2000, 'Inside Dhaka: 1–2 days · Outside Dhaka: 2–4 days', 'AH', true, '01712-345678', '01812-345678', '01912-3456789', '/demo/payment-qr.svg', 'Use Send Money for the total amount, then enter the number you paid from and the Transaction ID.', 'Limited time offer', 'Festive Sale — Up to 40% Off', 'Bridal sets, jhumkas, bangles and more. New designs added every week.', 'Shop the Sale', '/shop?sale=1', '/demo/promo.svg', '2026-12-31T17:59:00.000Z', '["/demo/products/gold-jhumka-earrings-1.svg","/demo/products/pearl-hair-clip-set-1.svg","/demo/products/bridal-choker-necklace-1.svg","/demo/products/golden-kundan-churi-set-1.svg","/demo/products/rose-glow-face-cream-1.svg","/demo/products/rose-gold-charm-bracelet-1.svg"]'::jsonb, 'https://www.openstreetmap.org/export/embed.html?bbox=90.3866%2C23.7837%2C90.4266%2C23.8037&layer=mapnik&marker=23.7937%2C90.4066', true);

insert into public.profile (full_name, professional_title, short_intro, bio, email, phone, location, profile_image_url, about_image_url, social_links) values
  ('Sumaiya Rahman', 'Founder, Artificial Home', 'From a small Facebook page to thousands of happy customers all over Bangladesh.', 'Artificial Home started in 2021 as a tiny Facebook page run from my bedroom in Dhaka. I loved jewellery but good designs were either too expensive or hard to find, so I started sourcing pieces I would wear myself.

Today we pack hundreds of orders every week — bangles, jhumkas, bridal sets, hair clips and gentle beauty care. Every piece is checked by hand before it leaves our studio, and we still read every message ourselves.

Thank you for being part of our story. We hope you find something that makes you smile.', 'hello@artificialhome.demo', '+880 1712-345678', 'Road 11, Banani, Dhaka', '/demo/avatar-owner.svg', '/demo/about-studio.svg', '[{"platform":"facebook","url":"https://facebook.com/"},{"platform":"instagram","url":"https://instagram.com/"},{"platform":"tiktok","url":"https://tiktok.com/"},{"platform":"youtube","url":"https://youtube.com/"},{"platform":"whatsapp","url":"https://wa.me/8801712345678"}]'::jsonb);

