insert into public.banners (kicker, title, subtitle, button_label, button_link, image_url, active, sort_order) values
  ('New Bridal Collection', 'Shine Brighter on Your Special Day', 'Handpicked kundan sets, jhumkas and tikli — made to make every moment golden.', 'Shop Bridal', '/shop/jewellery-sets', '/demo/banner-bridal.svg', true, 1),
  ('Festive Sale · Up to 40% Off', 'Jhumkas & Bangles You''ll Love', 'Trending designs for Eid, weddings and every party this season.', 'Shop the Sale', '/shop?sale=1', '/demo/banner-sale.svg', true, 2),
  ('Everyday Pearls', 'Little Details, Big Smiles', 'Pearl clips, dainty chains and studs for college, office and brunch.', 'Explore New In', '/shop?new=1', '/demo/banner-pearls.svg', true, 3);

insert into public.testimonials (name, role, company, project_title, quote, avatar_url, rating, active, sort_order) values
  ('Nusrat Jahan', 'Dhaka', null, 'Bridal Goina Set', 'I wore the bridal set on my holud and everyone asked where I got it! It looks exactly like the pictures and the packaging was so pretty.', '/demo/avatar-1.svg', 5, true, 1),
  ('Tasnim Akter', 'Chattogram', null, 'Gold Jhumka Earrings', 'Delivery to Chattogram took just 2 days. The jhumkas are light and don''t hurt my ears even after a full day.', '/demo/avatar-2.svg', 5, true, 2),
  ('Sadia Islam', 'Sylhet', null, 'Pearl Hair Clip Set', 'Ordered with bKash and they confirmed on WhatsApp within minutes. The pearl clips are my new favourite for college.', '/demo/avatar-3.svg', 5, true, 3),
  ('Farzana Rahman', 'Rajshahi', null, 'Rose Glow Face Cream', 'The rose cream is so light and smells lovely. My skin feels soft all day. Already ordered my second jar!', '/demo/avatar-4.svg', 4, true, 4);

insert into public.faqs (question, answer, active, sort_order) values
  ('How do I place an order?', 'Add products to your cart, go to Checkout, fill in your name, phone and address, choose a payment method and press Place Order. You can also order on WhatsApp.', true, 1),
  ('What are the delivery charges?', 'Inside Dhaka ৳60 and outside Dhaka ৳120. Orders over ৳2,000 get free delivery.', true, 2),
  ('How long does delivery take?', 'Inside Dhaka 1–2 working days, outside Dhaka 2–4 working days. We call you before sending the parcel.', true, 3),
  ('Which payment methods do you accept?', 'Cash on Delivery all over Bangladesh, plus bKash, Nagad, Rocket and Bangla QR. For mobile payments, send the total and enter your Transaction ID at checkout.', true, 4),
  ('Can I return or exchange a product?', 'Yes. If a product arrives damaged or different from the picture, tell us within 3 days with a photo and we will exchange it for free.', true, 5),
  ('Is the jewellery safe for sensitive skin?', 'Our pieces use skin-friendly, nickel-free plating. Keep them away from water and perfume to keep the shine for longer.', true, 6);

insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category, read_time, published_at, status) values
  ('How to Keep Your Artificial Jewellery Shining for Years', 'care-for-artificial-jewellery', 'Five simple habits that keep your favourite pieces looking brand new.', 'Artificial jewellery can last for years with a little care. These habits make the biggest difference.

## 1. Put it on last
Wear your jewellery after perfume, lotion and hairspray, not before.

## 2. Keep it dry
Take it off before a shower, a swim or washing your hands.

## 3. Wipe after wearing
A soft, dry cloth removes sweat and oil that make plating dull.

## 4. Store pieces separately
Use the zip pouch or a soft box so pieces don''t scratch each other.

## 5. Add silica gel
A small silica packet in your jewellery box keeps moisture away.', '/demo/blog-care.svg', 'Jewellery Care', '3 min read', '2026-09-20', 'published'),
  ('5 Jewellery Trends Every Girl Will Love This Season', 'jewellery-trends-this-season', 'From oversized jhumkas to pearl hair clips — here is what everyone is wearing.', 'This season is all about mixing traditional and modern.

## Oversized jhumkas
Big bells with pearl drops look amazing with both saree and kurti.

## Pearl everything
Pearl clips, pearl bracelets and layered pearl necklaces are everywhere.

## Stacked bangles
Mix velvet, glass and metal churi in two or three colours.

## Dainty pendants
A tiny heart or initial pendant is perfect for college and office.

## Claw clips
Matte butterfly claw clips are the easiest way to look put-together in seconds.', '/demo/blog-trends.svg', 'Style Guide', '4 min read', '2026-09-05', 'published'),
  ('Choosing Earrings for Your Face Shape', 'earrings-for-your-face-shape', 'A quick guide to finding earrings that flatter you the most.', 'The right earrings can brighten your whole look. Here is a simple guide.

## Round face
Long drops and chandbalis add length.

## Oval face
Lucky you — almost everything works, from studs to big jhumkas.

## Square face
Round hoops and soft pearl drops soften strong angles.

## Heart face
Earrings that are wider at the bottom, like jhumkas, balance a narrow chin.', '/demo/blog-earrings.svg', 'Style Guide', '3 min read', '2026-08-18', 'published');

commit;

